import numpy as np
from scipy.special import erf
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64)
def gelu(z): return 0.5*z*(1+erf(z/np.sqrt(2)))
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
k2=384
ec,Vc=np.linalg.eigh(np.cov(C9.T)); Q=Vc[:,:k2]
mM=M9.mean(0); sM=M9.std(0); Ms=(M9-mM)/sM
_,_,VtM=np.linalg.svd(Ms,full_matrices=False); PM=VtM[:k2].T
sc=Ms@PM; mC=C9.mean(0)
def build(lam):
    u=C9-mC+lam*sc@Q.T; mu=u.mean(1,keepdims=True); s=np.sqrt(((u-mu)**2).mean(1,keepdims=True))
    return (u-mu)/s, s
def cv(x,lams,b,t,wl):
    G=x@x.T/768.
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f; Y=np.eye(8)[y[tr]]-1/8
            Z=np.concatenate([wl*x,gelu(b*G[:,tr]-t)],1)
            for l in lams:
                Wt,bb=ridge_W(Z[tr],Y,l); res[l]+=((Z[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
for lam in [0.05,0.1,0.2]:
    x,s=build(lam); G=x@x.T/768; np.fill_diagonal(G,-1)
    print('lam',lam,'sig pct',np.round(np.percentile(s,[1,50,99]),3),'nn cos med',np.round(np.median(G.max(1)),3))
    print('  lin', cv(x,[1,3,10,30],0,0,1.0))
    for b,t in [(10,4.5),(10,6),(15,9)]:
        print('  ',b,t, cv(x,[3,10,30],b,t,1.0))
